from pathlib import Path
import json
import subprocess

evidence = Path("runtime/generated/evidence")
evidence.mkdir(parents=True, exist_ok=True)

def read(path):
    p = evidence / path
    return p.read_text(errors="replace") if p.exists() else None

def command(cmd):
    try:
        result = subprocess.run(
            cmd,
            text=True,
            capture_output=True,
            timeout=30,
        )
        return {
            "returncode": result.returncode,
            "stdout": result.stdout,
            "stderr": result.stderr,
        }
    except Exception as exc:
        return {
            "error": f"{type(exc).__name__}: {exc}"
        }

summary = {
    "github": {
        "repository": "${{ github.repository }}",
        "run_id": "${{ github.run_id }}",
        "run_attempt": "${{ github.run_attempt }}",
        "event": "${{ github.event_name }}",
        "pr_number": "${{ github.event.pull_request.number }}",
        "base_sha": "${{ github.event.pull_request.base.sha }}",
        "head_sha": "${{ github.event.pull_request.head.sha }}",
    },
    "git": {
        "head": command(["git", "rev-parse", "HEAD"]),
        "status": command(["git", "status", "--short", "--branch"]),
        "merge_base": command([
            "git", "merge-base",
            "${{ github.event.pull_request.head.sha }}",
            "${{ github.event.pull_request.base.sha }}"
        ]),
    },
    "verification": {
        "quick_result": read("verify-quick.result"),
        "backend_result": read("verify-backend.result"),
        "quick_stdout": read("verify-quick.stdout.log"),
        "backend_stdout": read("verify-backend.stdout.log"),
        "report": read("../verification-report.md"),
    },
    "black": {
        "version": read("black-version.txt"),
        "matrix": read("black-check-matrix.txt"),
        "fast_check_diag": read("fast-check-black-diag.txt"),
        "shell_diff": read("shell-differential.txt"),
        "inventory": read("black-file-inventory.txt"),
    },
    "evidence_files": sorted(
        str(p.relative_to(evidence))
        for p in evidence.rglob("*")
        if p.is_file()
    ),
}

(evidence / "diagnostic-summary.json").write_text(
    json.dumps(summary, indent=2)
)
